def group_existing_tasks(apps, schema_editor):
    # Oturumlardan önce sorulmuş soruları kaybetmemek için firmaya göre "Eski sohbet" oturumlarına topla.
    ChatSession = apps.get_model("core", "ChatSession")
    TaskResult = apps.get_model("core", "TaskResult")
    company_ids = TaskResult.objects.filter(session__isnull=True).order_by().values_list("company_id", flat=True).distinct()
    for company_id in company_ids:
        session = ChatSession.objects.create(title="Eski sohbet", company_id=company_id)
        TaskResult.objects.filter(session__isnull=True, company_id=company_id).update(session=session)


